    return { action: "verify" };
  }
  const dx = state.target[0] - state.tip[0];
  const dy = state.target[1] - state.tip[1];

  if (state.history && state.history.length >= 2) {
    let sumU1Sq = 0, sumU2Sq = 0;
    let sumDxU1 = 0, sumDyU2 = 0;
    for (const h of state.history) {
      if (h.applied && h.delta && !h.limited) {
        sumU1Sq += h.applied[0] * h.applied[0];
        sumU2Sq += h.applied[1] * h.applied[1];
        sumDxU1 += h.delta[0] * h.applied[0];
        sumDyU2 += h.delta[1] * h.applied[1];
      }
    }
    const gainX = sumU1Sq > 1e-5 ? sumDxU1 / sumU1Sq : 0;
    const gainY = sumU2Sq > 1e-5 ? sumDyU2 / sumU2Sq : 0;
    if (Math.abs(gainX) > 1 && Math.abs(gainY) > 1) {
      let du1 = dx / gainX;
      let du2 = dy / gainY;
      const m = Math.max(Math.abs(du1), Math.abs(du2));
      if (m > 0) {
        const targetMag = state.errorPx > 40 ? 0.1 : Math.max(0.01, 0.1 * (state.errorPx / 40));
        du1 = (du1 / m) * targetMag;
        du2 = (du2 / m) * targetMag;
      }
      return { action: "move", u: [Math.max(-0.1, Math.min(0.1, du1)), Math.max(-0.1, Math.min(0.1, du2))] };
    }
  }

  const len = Math.sqrt(dx * dx + dy * dy);
