  if (state.errorPx <= state.tolerancePx) {
    return { action: "verify" };
  }

  // 收集有效歷史以估計局部 Jacobian
  const validHistory = history.filter(h => h.delta && (Math.abs(h.delta[0]) > 0.05 || Math.abs(h.delta[1]) > 0.05));
  let J = null;
  if (validHistory.length >= 3) {
    const recent = validHistory.slice(-8);
    let sumU00 = 0, sumU01 = 0, sumU10 = 0, sumU11 = 0;
    let sumDXU0 = 0, sumDXU1 = 0, sumDYU0 = 0, sumDYU1 = 0;

    for (const h of recent) {
      const u0 = h.applied[0];
      const u1 = h.applied[1];
      sumU00 += u0 * u0;
      sumU01 += u0 * u1;
      sumU10 += u1 * u0;
      sumU11 += u1 * u1;
      sumDXU0 += h.delta[0] * u0;
      sumDXU1 += h.delta[0] * u1;
      sumDYU0 += h.delta[1] * u0;
      sumDYU1 += h.delta[1] * u1;
    }

    const det = sumU00 * sumU11 - sumU01 * sumU10;
    if (Math.abs(det) > 1e-6) {
      const j00 = (sumDXU0 * sumU11 - sumDXU1 * sumU10) / det;
      const j01 = (sumDXU1 * sumU00 - sumDXU0 * sumU01) / det;
      const j10 = (sumDYU0 * sumU11 - sumDYU1 * sumU10) / det;
      const j11 = (sumDYU1 * sumU00 - sumDYU0 * sumU01) / det;
      J = [[j00, j01], [j10, j11]];
    }
  }

  let u = [0.08, 0];
