    throw new Error("Invalid JSON: " + e.message);
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Reply must be a non-null object");
  }
  if (parsed.ok !== true) {
    throw new Error(parsed.error || "Device replied with ok: false");
  }
  const applied = parsed.accepted !== undefined ? parsed.accepted : parsed.applied;
  if (applied === undefined) {
    throw new Error("Missing accepted or applied field");
  }
  return {
    applied: applied,
    limited: Boolean(parsed.limited)
  };
}
